import json
def solve(inp):
    out=[r[:] for r in inp]; H,W=len(inp),len(inp[0])
    bg=max(set(x for r in inp for x in r), key=lambda c:sum(r.count(c) for r in inp))
    import collections
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            v=inp[i][j]
            if v==bg: continue
            # flood fill component of non-bg same color
            comp=[]; stack=[(i,j)]; seen[i][j]=True
            while stack:
                a,b=stack.pop(); comp.append((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and inp[x][y]==v:
                            seen[x][y]=True; stack.append((x,y))
            rs=[c[0] for c in comp]; cs=[c[1] for c in comp]
            rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
            area=(rmax-rmin+1)*(cmax-cmin+1)-len(comp)
            col=2 if area%2==0 else 7
            for a in range(rmin+1,rmax):
                for b in range(cmin+1,cmax):
                    out[a][b]=col
    return out
